create function public.lock_application_for_document() returns trigger language plpgsql security definer set search_path='' as $$ begin perform 1 from public.applications where id=new.application_id and user_id=new.user_id for update; if not found then raise exception 'Application unavailable'; end if; new.created_at=clock_timestamp(); return new; end $$;
create trigger application_document_lock before insert on public.application_documents for each row execute function public.lock_application_for_document();
create function public.reset_changed_answer_confirmation() returns trigger language plpgsql set search_path='' as $$ begin if old.question is distinct from new.question or old.answer is distinct from new.answer or old.sensitive is distinct from new.sensitive then new.confirmed=false; end if; return new; end $$;
create trigger question_reconfirm before update on public.application_questions for each row execute function public.reset_changed_answer_confirmation();
